let state='boot', carouselKey=null, carouselIdx=0, acIdx=0;
let charIsSkull = false;

function show(id){
  ['vBoot','vMenu','vSubAbout','vCarousel','vAnimeCarousel','vProjects','vSkills','vJourney','vPanel'].forEach(v=>{
    const el=document.getElementById(v);
    el.classList.remove('active');el.style.display='none';
  });
  const t=document.getElementById(id);
  t.style.display='flex';
  void t.offsetWidth;
  t.classList.add('active');
}

/* â”€â”€ HOBBY CAROUSEL â”€â”€ */
function buildCarousel(key){
  carouselKey=key; carouselIdx=0;
  renderCarousel();
}

function renderCarousel(){
  const data=CAROUSELS[carouselKey];
  const cards=data.cards;
  const stage=document.getElementById('carouselStage');
  const dots=document.getElementById('carouselDots');
  document.getElementById('carouselTitle').textContent=data.title;
  stage.innerHTML=''; dots.innerHTML='';

  cards.forEach((card,i)=>{
    const diff=i-carouselIdx;
    let pos='hidden';
    if(diff===0)pos='center';
    else if(diff===-1)pos='left1';
    else if(diff===1)pos='right1';
    else if(diff===-2)pos='left2';
    else if(diff===2)pos='right2';

    const el=document.createElement('div');
    const isAnime=card.type==='anime';
    el.className='c-card '+(isAnime?'anime-card ':'') + pos;

    if(isAnime){
      // special anime card with bg image and logo
      const bg=document.createElement('div');
      bg.className='anime-bg';
      bg.style.backgroundImage='url('+ANIME_BG+')';
      const logoWrap=document.createElement('div');
      logoWrap.className='anime-logo-wrap';
      const animeLabel=document.createElement('div');
      animeLabel.style.cssText='font-family:\'Press Start 2P\',monospace;font-size:7px;color:#4ade80;letter-spacing:1px;text-align:center;margin-bottom:3px';
      animeLabel.textContent='ANIME';
      const sub=document.createElement('div');
      sub.className='anime-sub';sub.textContent='TAP A TO BROWSE';
      logoWrap.appendChild(animeLabel);logoWrap.appendChild(sub);
      el.appendChild(bg);el.appendChild(logoWrap);
      if(diff<0)el.onclick=()=>carouselMove(-1);
      else if(diff>0)el.onclick=()=>carouselMove(1);
      else el.onclick=()=>openAnimeCarousel();
    } else {
      const iconWrap=document.createElement('div');
      iconWrap.className='c-icon-px';
      iconWrap.style.cssText='display:flex;align-items:center;justify-content:center;margin:0 auto 6px;min-height:36px';
      if(card.svgIcon){
        iconWrap.innerHTML=card.svgIcon;
        const svgEl=iconWrap.querySelector('svg');
        if(svgEl&&pos!=='center'){svgEl.style.opacity='0.45';}
      } else {
        iconWrap.style.cssText='display:grid;grid-template-columns:repeat(5,7px);gap:1px;margin:0 auto 6px';
        (card.icon||[]).flat().forEach(v=>{
          const px=document.createElement('div');
          px.style.cssText='width:7px;height:7px;border-radius:1px;background:'+(v?(pos==='center'?'#4ade80':'#4ade8066'):'transparent');
          iconWrap.appendChild(px);
        });
      }
      const name=document.createElement('div');
      name.className='c-card-name';name.textContent=card.name;
      const desc=document.createElement('div');
      desc.className='c-card-desc';
      desc.innerHTML=card.desc.replace(/\\n/g,'<br>');
      el.appendChild(iconWrap);el.appendChild(name);el.appendChild(desc);
      if(diff<0)el.onclick=()=>carouselMove(-1);
      else if(diff>0)el.onclick=()=>carouselMove(1);
    }

    stage.appendChild(el);

    const dot=document.createElement('div');
    dot.className='c-dot'+(i===carouselIdx?' active':'');
    dot.onclick=()=>{carouselIdx=i;renderCarousel();};
    dots.appendChild(dot);
  });
}

function carouselMove(dir){
  const len=CAROUSELS[carouselKey].cards.length;
  carouselIdx=Math.max(0,Math.min(len-1,carouselIdx+dir));
  renderCarousel();
}

/* â”€â”€ ANIME CAROUSEL â”€â”€ */
function openAnimeCarousel(){
  acIdx=0;
  renderAnimeCarousel();
  state='animecarousel';
  show('vAnimeCarousel');
  setTimeout(updateTrailer, 100);
}

function renderAnimeCarousel(){
  const stage=document.getElementById('acStage');
  const dots=document.getElementById('acDots');
  stage.innerHTML=''; dots.innerHTML='';

  ANIME_LIST.forEach((anime,i)=>{
    const diff=i-acIdx;
    let pos='hidden';
    if(diff===0)pos='center';
    else if(diff===-1)pos='left1';
    else if(diff===1)pos='right1';
    else if(diff===-2)pos='left2';
    else if(diff===2)pos='right2';

    const el=document.createElement('div');
    el.className='ac-card '+pos;

    if(anime.img){
      const img=document.createElement('img');
      img.className='ac-img';img.src=anime.img;img.alt=anime.name;
      el.appendChild(img);
    } else {
      const ph=document.createElement('div');
      ph.style.cssText='width:100%;height:96px;background:#111;display:flex;align-items:center;justify-content:center;font-size:6px;color:#4ade8033;letter-spacing:1px';
      ph.textContent='+ ADD ANIME';
      el.appendChild(ph);
    }

    const wrap=document.createElement('div');
    wrap.className='ac-logo-wrap';

    const nm=document.createElement('div');
    nm.className='ac-name';nm.textContent=anime.name;
    const gn=document.createElement('div');
    gn.className='ac-genre';gn.textContent=anime.genre;
    wrap.appendChild(nm);wrap.appendChild(gn);
    el.appendChild(wrap);

    if(diff<0)el.onclick=()=>acMove(-1);
    else if(diff>0)el.onclick=()=>acMove(1);

    stage.appendChild(el);

    const dot=document.createElement('div');
    dot.className='ac-dot'+(i===acIdx?' active':'');
    dot.onclick=()=>{acIdx=i;renderAnimeCarousel();};
    dots.appendChild(dot);
  });
}

function updateTrailer(){
  const anime = ANIME_LIST[acIdx];
  const bg = document.getElementById('trailerBg');
  const overlay = document.getElementById('trailerOverlay');
  if(anime && anime.trailer){
    bg.innerHTML = '<iframe src="https://www.youtube.com/embed/'+anime.trailer+'?autoplay=1&mute=1&loop=1&playlist='+anime.trailer+'&controls=0&showinfo=0&rel=0&modestbranding=1" allow="autoplay; encrypted-media" allowfullscreen></iframe>';
    bg.style.display='block';
    overlay.style.display='block';
  } else {
    bg.innerHTML='';
    bg.style.display='none';
    overlay.style.display='none';
  }
}

function acMove(dir){
  acIdx=Math.max(0,Math.min(ANIME_LIST.length-1,acIdx+dir));
  renderAnimeCarousel();
  updateTrailer();
}

function animeBack(){
  const bg=document.getElementById('trailerBg');
  const overlay=document.getElementById('trailerOverlay');
  if(bg){bg.innerHTML='';bg.style.display='none';}
  if(overlay)overlay.style.display='none';
  state='carousel';
  show('vCarousel');
}

