(function clock(){
  let lastTriggerMin = -1;
  function tick(){
    const n=new Date();
    document.getElementById('clk').textContent=String(n.getHours()).padStart(2,'0')+':'+String(n.getMinutes()).padStart(2,'0');
    const m = n.getMinutes();
    if(m % 10 === 0 && m !== lastTriggerMin){
      lastTriggerMin = m;
      triggerSkullEvent();
    }
  }
  tick();setInterval(tick,15000);
})();

let evilLaughInterval = null;
let laughChars = ['HA','HA','HE','☠','HE','HA'];
let laughIdx = 0;

function triggerEvilLaugh(){
  const nameEl = document.getElementById('aboutNameLabel');
  const roleEl = document.getElementById('aboutRoleLabel');
  const outerEl = document.getElementById('aboutGifOuter');
  const gifAnim = document.getElementById('gifAnim');
  const gbIcon = document.getElementById('gbIconImg');

  // Swap pixel char for skull GIF
  const skullGif = document.getElementById('skullGifImg');
  if(gifAnim) gifAnim.style.display='none';
  if(gbIcon) gbIcon.style.display='none';
  if(skullGif){
    skullGif.style.display='block';
    skullGif.style.animation='iconShake 0.35s ease-in-out infinite';
  }
  if(outerEl){
    outerEl.style.animation='redPulseOuter .5s ease-in-out infinite';
    outerEl.style.borderColor='#ff4444';
    outerEl.style.background='#3a0000';
  }
  if(nameEl){nameEl.style.animation='evilPulse .4s ease-in-out infinite';nameEl.style.color='#ff4444';}
  if(roleEl){
    roleEl.style.animation='laughFloat .5s ease-in-out infinite';
    roleEl.style.color='#ff4444';
    evilLaughInterval = setInterval(()=>{
      roleEl.textContent = laughChars[laughIdx % laughChars.length];
      laughIdx++;
    }, 200);
  }
}

function stopEvilLaugh(){
  const nameEl = document.getElementById('aboutNameLabel');
  const roleEl = document.getElementById('aboutRoleLabel');
  const outerEl = document.getElementById('aboutGifOuter');
  const gifAnim = document.getElementById('gifAnim');
  const gbIcon = document.getElementById('gbIconImg');

  if(nameEl)nameEl.style.cssText='';
  if(roleEl){roleEl.style.cssText='';roleEl.textContent='FULL-STACK DEVELOPER';}
  if(outerEl){outerEl.style.animation='';outerEl.style.borderColor='';outerEl.style.background='';}
  if(gifAnim)gifAnim.style.display='';
  if(gbIcon){gbIcon.style.display='none';gbIcon.style.animation='';gbIcon.style.filter='';}
  const skullGifEl=document.getElementById('skullGifImg');
  if(skullGifEl){skullGifEl.style.display='none';skullGifEl.style.animation='';}
  if(evilLaughInterval){clearInterval(evilLaughInterval);evilLaughInterval=null;}
  laughIdx=0;
}

function triggerSkullEvent(){
  // Don't trigger during games or while already skulling
  if(projActiveKey) return;
  if(charIsSkull) return;

  charIsSkull = true;
  triggerEvilLaugh();

  // Screen shake
  const wrap = document.querySelector('.gb-wrap');
  wrap.style.animation='screenShake 0.6s ease';
  setTimeout(()=>{wrap.style.animation='';},700);

  // Show overlay
  const overlay = document.getElementById('skullOverlay');
  overlay.classList.add('active');

  const canvas = document.getElementById('skullCanvas');
  const ctx = canvas.getContext('2d');
  canvas.width = canvas.offsetWidth || 400;
  canvas.height = canvas.offsetHeight || 340;

  const skulls = Array.from({length:22},()=>({
    x: Math.random()*canvas.width,
    y: canvas.height + Math.random()*200,
    speed: 0.9 + Math.random()*1.4,
    size: 12 + Math.random()*18,
    blink: Math.random()>0.3,
    blinkTimer: Math.floor(Math.random()*20),
  }));

  function drawSkulls(){
    ctx.clearRect(0,0,canvas.width,canvas.height);
    skulls.forEach(s=>{
      s.y -= s.speed;
      s.blinkTimer++;
      const vis = s.blink ? (Math.floor(s.blinkTimer/7)%2===0) : true;
      if(!vis) return;
      ctx.save();
      ctx.globalAlpha = Math.min(1, Math.max(0, s.y / canvas.height));
      ctx.fillStyle='#ff4444';
      ctx.font=`${s.size}px monospace`;
      ctx.textAlign='center';
      ctx.fillText('☠',s.x,s.y);
      ctx.restore();
    });
    if(skulls.some(s=>s.y>-40)){
      requestAnimationFrame(drawSkulls);
    } else {
      ctx.clearRect(0,0,canvas.width,canvas.height);
      overlay.classList.remove('active');
      charIsSkull = false;
      stopEvilLaugh();
    }
  }
  drawSkulls();
}
